-- 第六阶段：新增资料工具、备份作业与控制台维护记录。不得重跑。
CREATE TABLE classes(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,course_type_id TEXT NOT NULL,teacher_id TEXT NOT NULL,location_id TEXT,date_from TEXT NOT NULL,date_to TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,course_type_id) REFERENCES course_types(tenant_id,id),FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id),FOREIGN KEY(tenant_id,location_id) REFERENCES locations(tenant_id,id));
CREATE TABLE class_members(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,class_id TEXT NOT NULL,student_id TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,class_id) REFERENCES classes(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE followup_notes(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,at TEXT NOT NULL,content TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE followup_tasks(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT,title TEXT NOT NULL,due_date TEXT NOT NULL,assignee_id TEXT,legacy_owner TEXT NOT NULL DEFAULT '',done INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id),FOREIGN KEY(tenant_id,assignee_id) REFERENCES users(tenant_id,id));
CREATE TABLE student_routines(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,weekday INTEGER NOT NULL,time TEXT NOT NULL,content TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE leads(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,name TEXT NOT NULL,phone_enc TEXT,parent_phone_enc TEXT,phone_last4 TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL DEFAULT 'new' CHECK(stage IN ('new','contacted','trial','enrolled','lost')),next_followup TEXT,trial_at TEXT,grade TEXT NOT NULL DEFAULT '',direction TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',student_id TEXT,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE referrals(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,name TEXT NOT NULL,grade TEXT NOT NULL DEFAULT '',direction TEXT NOT NULL DEFAULT '',intention TEXT NOT NULL,parent_phone_enc TEXT NOT NULL,consent_name TEXT NOT NULL,consent_at TEXT NOT NULL,consent_method TEXT NOT NULL,consent_operator TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','received','withdrawn')),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE announcement_reads(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,announcement_id TEXT NOT NULL,user_id TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE UNIQUE INDEX class_member_once ON class_members(tenant_id,class_id,student_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX announcement_read_once ON announcement_reads(tenant_id,announcement_id,user_id) WHERE deleted_at IS NULL;
CREATE INDEX followup_due ON followup_tasks(tenant_id,done,due_date);
CREATE INDEX lead_stages ON leads(tenant_id,stage,next_followup);
CREATE INDEX referral_status ON referrals(tenant_id,status,created_at);
ALTER TABLE tenant_branding ADD COLUMN contact_text TEXT NOT NULL DEFAULT '';
CREATE TABLE platform_announcements(id TEXT PRIMARY KEY,title TEXT NOT NULL,content TEXT NOT NULL,roles TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER,created_at INTEGER NOT NULL,created_by TEXT NOT NULL);
CREATE TABLE announcement_targets(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,announcement_id TEXT NOT NULL REFERENCES platform_announcements(id),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,announcement_id));
CREATE TABLE maintenance_leases(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,admin_id TEXT NOT NULL,reason TEXT NOT NULL,expires_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,id));
CREATE TABLE data_jobs(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('legacy','restore')),status TEXT NOT NULL CHECK(status IN ('staging','ready','completed','cancelled')),source_tenant TEXT,manifest_json TEXT NOT NULL,created_at INTEGER NOT NULL,admin_id TEXT NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE UNIQUE INDEX one_data_job ON data_jobs(tenant_id) WHERE status IN ('staging','ready');
CREATE TABLE data_job_rows(tenant_id TEXT NOT NULL,id TEXT NOT NULL,job_id TEXT NOT NULL,table_name TEXT NOT NULL,row_id TEXT NOT NULL,row_json TEXT NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,job_id) REFERENCES data_jobs(tenant_id,id),UNIQUE(tenant_id,job_id,table_name,row_id));
CREATE TABLE trusted_imports(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE backup_runs(id TEXT PRIMARY KEY,at INTEGER NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL);
DROP TRIGGER IF EXISTS ledger_no_update;
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON package_transactions WHEN NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'append only'); END;
DROP TRIGGER IF EXISTS ledger_no_delete;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON package_transactions WHEN NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'append only'); END;
DROP TRIGGER IF EXISTS snapshot_no_update;
CREATE TRIGGER snapshot_no_update BEFORE UPDATE ON payroll_snapshots WHEN NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'append only'); END;
DROP TRIGGER IF EXISTS snapshot_no_delete;
CREATE TRIGGER snapshot_no_delete BEFORE DELETE ON payroll_snapshots WHEN NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'append only'); END;
DROP TRIGGER IF EXISTS course_limits_course_types_insert;
CREATE TRIGGER course_limits_course_types_insert BEFORE INSERT ON course_types WHEN NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) AND ((NEW.units_per_lesson<1 OR NEW.default_minutes NOT IN (30,45,60))) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
DROP TRIGGER IF EXISTS course_limits_schedule_templates_insert;
CREATE TRIGGER course_limits_schedule_templates_insert BEFORE INSERT ON schedule_templates WHEN NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) AND ((NEW.units<1 OR NEW.duration NOT IN (30,45,60))) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
DROP TRIGGER IF EXISTS course_limits_lessons_insert;
CREATE TRIGGER course_limits_lessons_insert BEFORE INSERT ON lessons WHEN NOT EXISTS(SELECT 1 FROM trusted_imports WHERE tenant_id=NEW.tenant_id) AND ((NEW.units<1 OR NEW.duration NOT IN (30,45,60))) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
ALTER TABLE lessons ADD COLUMN class_id TEXT;
CREATE TRIGGER lessons_class_insert BEFORE INSERT ON lessons WHEN NEW.class_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM classes WHERE tenant_id=NEW.tenant_id AND id=NEW.class_id) THEN RAISE(ABORT,'invalid_class_reference') END; END;
CREATE TRIGGER lessons_class_update BEFORE UPDATE OF class_id ON lessons WHEN NEW.class_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM classes WHERE tenant_id=NEW.tenant_id AND id=NEW.class_id) THEN RAISE(ABORT,'invalid_class_reference') END; END;
ALTER TABLE schedule_templates ADD COLUMN class_id TEXT;
CREATE TRIGGER schedule_templates_class_insert BEFORE INSERT ON schedule_templates WHEN NEW.class_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM classes WHERE tenant_id=NEW.tenant_id AND id=NEW.class_id) THEN RAISE(ABORT,'invalid_class_reference') END; END;
CREATE TRIGGER schedule_templates_class_update BEFORE UPDATE OF class_id ON schedule_templates WHEN NEW.class_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM classes WHERE tenant_id=NEW.tenant_id AND id=NEW.class_id) THEN RAISE(ABORT,'invalid_class_reference') END; END;
-- Immutable per-record staging snapshot: one atomic D1 batch captures the database; Cron encrypts bounded pages.
CREATE TABLE backup_snapshots(id TEXT PRIMARY KEY,at INTEGER NOT NULL,status TEXT NOT NULL,manifest_json TEXT NOT NULL);
CREATE UNIQUE INDEX one_running_backup ON backup_snapshots(status) WHERE status='running';
CREATE TABLE backup_snapshot_rows(tenant_id TEXT NOT NULL,id TEXT NOT NULL,snapshot_id TEXT NOT NULL REFERENCES backup_snapshots(id),table_name TEXT NOT NULL,source_id TEXT NOT NULL,row_json TEXT NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE INDEX backup_page ON backup_snapshot_rows(snapshot_id,table_name,source_id,tenant_id);
